import{_ as n,o as e,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Repository Organisation","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/organisation.md","filePath":"architecture/organisation.md","lastUpdated":null}'),t={name:"architecture/organisation.md"};function o(p,a,r,l,c,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="repository-organisation" tabindex="-1">Repository Organisation <a class="header-anchor" href="#repository-organisation" aria-label="Permalink to &quot;Repository Organisation&quot;">​</a></h1><p><strong>Status:</strong> Approved<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="target-structure" tabindex="-1">Target structure <a class="header-anchor" href="#target-structure" aria-label="Permalink to &quot;Target structure&quot;">​</a></h2><p>Archie MUST be organised around cohesive application responsibilities:</p><div class="language-tree vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tree</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmd/</span></span>
<span class="line"><span>  archied/</span></span>
<span class="line"><span>  archie-agent/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>internal/</span></span>
<span class="line"><span>  domain/</span></span>
<span class="line"><span>    &lt;area&gt;/</span></span>
<span class="line"><span>  eventbus/</span></span>
<span class="line"><span>  policy/</span></span>
<span class="line"><span>  infrastructure/</span></span>
<span class="line"><span>    configuration/</span></span>
<span class="line"><span>    eventbus/</span></span>
<span class="line"><span>      nats/</span></span>
<span class="line"><span>    forge/</span></span>
<span class="line"><span>    persistence/</span></span>
<span class="line"><span>    &lt;external-service&gt;/</span></span>
<span class="line"><span>  app/</span></span>
<span class="line"><span>    archied/</span></span>
<span class="line"><span>    agentworker/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>plugins/</span></span>
<span class="line"><span>  &lt;plugin&gt;/</span></span>
<span class="line"><span>deployments/</span></span>
<span class="line"><span>  &lt;supported-assembly&gt;/</span></span>
<span class="line"><span>docs/</span></span>
<span class="line"><span>  guides/</span></span>
<span class="line"><span>examples/</span></span>
<span class="line"><span>  &lt;copyable-example&gt;/</span></span>
<span class="line"><span>extras/</span></span>
<span class="line"><span>  &lt;optional-extension&gt;/</span></span></code></pre></div><p>Domain names are chosen from application behaviour during package review. Existing names MUST NOT be retained merely to reduce migration work.</p><h2 id="domain-areas" tabindex="-1">Domain areas <a class="header-anchor" href="#domain-areas" aria-label="Permalink to &quot;Domain areas&quot;">​</a></h2><p>A domain owns one cohesive job performed by Archie. It contains that job&#39;s language, state, rules, operations, commands, events, policy implementations, runtime settings, and required service contracts.</p><p>Code that changes together SHOULD live together. Empty or ceremonial <code>entities</code>, <code>repositories</code>, or <code>services</code> layers are prohibited.</p><h2 id="application-composition" tabindex="-1">Application composition <a class="header-anchor" href="#application-composition" aria-label="Permalink to &quot;Application composition&quot;">​</a></h2><p><code>internal/app</code>:</p><ul><li>constructs domains and infrastructure implementations;</li><li>translates external configuration into domain and plugin settings;</li><li>connects commands, events, and shared contracts;</li><li>starts services in dependency order;</li><li>owns health aggregation and shutdown ordering.</li></ul><p><code>cmd/*</code> parses only process-level input and invokes the relevant application composition package. It MUST NOT contain substantive wiring or act as a service locator.</p><h2 id="process-boundaries" tabindex="-1">Process boundaries <a class="header-anchor" href="#process-boundaries" aria-label="Permalink to &quot;Process boundaries&quot;">​</a></h2><p>Archie begins as a modular monolith even when capabilities run in separate processes. A domain becomes a separately deployed service only for a concrete need such as security isolation, independent scaling, failure containment, or independent operation.</p><p>Possible future extraction does not justify premature network protocols or duplicated service scaffolding.</p><h2 id="optional-and-operational-material" tabindex="-1">Optional and operational material <a class="header-anchor" href="#optional-and-operational-material" aria-label="Permalink to &quot;Optional and operational material&quot;">​</a></h2><ul><li><code>extras/&lt;extension&gt;</code> contains a maintained optional extension with real behaviour. Core Archie MUST NOT import it, and removing <code>extras/</code> MUST NOT prevent the core application from building or running.</li><li><code>deployments/&lt;assembly&gt;</code> contains a supported assembly, including deployment definitions and concise operational instructions.</li><li><code>docs/guides/</code> contains handwritten explanation and links to generated reference material.</li><li><code>examples/</code> contains copyable samples with explicit purpose, prerequisites, and support expectations.</li></ul><p>Supported assemblies SHOULD demonstrate that capabilities can be selected independently.</p>`,19)])])}const h=n(t,[["render",o]]);export{m as __pageData,h as default};
